import "./index.less"
import SearchSuggest from '../../common/components/search-suggest'
class InitPage {
    constructor(el) {
        this.DOM = {
            el: el
        };
        this.scrollContent = document.querySelector('.scroll-content')
        this.init();
    }
    init() {
        this.initEvents()
    }
    initEvents() {
        $(".blog-cate-wrapper .scroll-item").click((e) => {
            $(".blog-cate-wrapper .scroll-item").removeClass("active")
            e.currentTarget.classList.add("active")

            const target_name = $(e.currentTarget).find(".jky-text-lg").attr("data-anchor")
            let t_ = ''
            if (target_name == 'all') {
                t_ = ".blog-cate-list"
            } else {
                t_ = ".blog-cate-main[data-anchor='" + target_name + "']"
            }

            // 横向平滑滚动
            this.handleSmoothScroll(e.currentTarget)

            // 竖向平滑滚动
            $('html, body').animate({
                scrollTop: $(t_).offset().top - $('.blog-cate').height() - 20
            }, 300);
        })
    }
    // 横向平滑滚动
    handleSmoothScroll(item) {
        // 设置滑动时间为 500 毫秒
        const duration = 300;

        // 获取元素当前的滚动位置handleSmoothScroll
        const startScrollLeft = this.scrollContent.scrollLeft;

        const left = this.scrollContent.getBoundingClientRect().left

        const scrollLeft = left + item.offsetLeft + (item.offsetWidth / 2) - (window.innerWidth / 2);
        const targetScrollLeft = scrollLeft - startScrollLeft

        // 记录动画开始时间
        let startTime = null;

        // 处理横向滚动
        const smoothScroll = (currentTime) => {
            // 如果是第一次执行,记录开始时间
            if (!startTime) {
                startTime = currentTime;
            }

            // 计算已经经过的时间
            const elapsedTime = currentTime - startTime;

            // 计算当前滚动位置
            const scrollLeft = this.easeInOutQuad(elapsedTime, startScrollLeft, targetScrollLeft, duration);

            // 设置新的滚动位置
            this.scrollContent.scrollLeft = scrollLeft;

            // 如果滚动未完成,继续下一帧动画
            if (elapsedTime < duration) {
                requestAnimationFrame(smoothScroll);
            }
        }

        requestAnimationFrame(smoothScroll);
    }
    // 缓动函数,用于计算当前滚动位置
    easeInOutQuad(t, b, c, d) {
        t /= d / 2;
        if (t < 1) return (c / 2) * t * t + b;
        t--;
        return (-c / 2) * (t * (t - 2) - 1) + b;
    }
}

window.$(document).ready(function () {
    customElements.define('search-suggest', SearchSuggest);
    new InitPage()
})